function updateWildlife(dt,now){for(const animal of wildlife){const hunted=state.huntedAnimals.find(v=>v.id===animal.id);animal.alive=!hunted||state.day>=hunted.day+2;animal.group.visible=animal.alive;if(!animal.alive)continue;if(now>animal.turnAt||Math.hypot(animal.targetX-animal.group.position.x,animal.targetZ-animal.group.position.z)<.6){const angle=Math.random()*Math.PI*2,dist=3+Math.random()*7;animal.targetX=clamp(animal.group.position.x+Math.cos(angle)*dist,-88,88);animal.targetZ=clamp(animal.group.position.z+Math.sin(angle)*dist,-88,88);animal.turnAt=now+2200+Math.random()*3200;}const dx=animal.targetX-animal.group.position.x,dz=animal.targetZ-animal.group.position.z,d=Math.hypot(dx,dz);if(d>.15){const step=Math.min(d,animal.speed*dt);animal.group.position.x+=dx/d*step;animal.group.position.z+=dz/d*step;animal.group.rotation.y=Math.atan2(dx,dz);}animal.group.position.y=groundHeight(animal.group.position.x,animal.group.position.z)+Math.abs(Math.sin(now*.012+animal.phase))*.035;}}
