 for(let row=0;row<3;row++){const line=new THREE.Mesh(new THREE.BoxGeometry(3.35,.035,.12),furrow);line.position.set(0,.14,-1+row);g.add(line);}
 if(ghost){const edge=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(4.1,.3,3.5)),new THREE.LineBasicMaterial({color:0xb8ff65,transparent:true,opacity:.95,depthTest:false}));edge.position.y=.12;g.add(edge);}
