document.getElementById("sheep-pen-close").addEventListener("click",closeSheepPen);
sheepFeedButton.addEventListener("click",()=>{const pen=state.sheepPens[activeSheepPenIndex];if(!pen)return;const flock=state.sheep.filter(a=>a.penIndex===activeSheepPenIndex),hungry=flock.filter(a=>!a.woolReady&&a.fedDay!==state.day);if(!hungry.length){sheepPenStatus.textContent="As ovelhas já receberam alimento hoje ou aguardam a tosquia.";return;}if(state.inventory.wheat<hungry.length*2){sheepPenStatus.textContent="Você precisa de "+(hungry.length*2)+" trigos para alimentar todas as ovelhas (2 por animal).";return;}state.inventory.wheat-=hungry.length*2;hungry.forEach(a=>a.fedDay=state.day);saveState();renderSheepPen();renderCrafting();sheepPenStatus.textContent="As ovelhas foram alimentadas. A lã estará pronta depois de um dia de jogo.";});
sheepShearButton.addEventListener("click",()=>{const pen=state.sheepPens[activeSheepPenIndex];if(!pen)return;const ready=state.sheep.filter(a=>a.penIndex===activeSheepPenIndex&&a.woolReady);if(!ready.length)return;const amount=ready.length*2;ready.forEach(a=>a.woolReady=false);state.inventory.wool+=amount;saveState();renderSheepPen();renderCrafting();sheepPenStatus.textContent="Tosquia concluída: você obteve "+amount+" unidades de lã.";notify("Lã coletada: +"+amount+".");});
function openCooking(){cookingPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderCooking();cookStatus.textContent="Use bagas e um galho para preparar uma refeição na fogueira."; }
function renderCooking(){const cook=document.getElementById("cook-meal"),cookMeat=document.getElementById("cook-meat"),eat=document.getElementById("eat-meal");if(cook)cook.disabled=state.inventory.berries<2||state.inventory.branches<1;if(cookMeat)cookMeat.disabled=state.inventory.meat<1||state.inventory.branches<1;if(eat)eat.disabled=state.inventory.meals<1||state.hunger>=100;document.getElementById("cook-inventory").textContent="Bagas: "+state.inventory.berries+" · Galhos: "+state.inventory.branches+" · Carne: "+state.inventory.meat+" · Refeições prontas: "+state.inventory.meals+" · Fome: "+Math.round(state.hunger)+"%";}
document.getElementById("cooking-close").addEventListener("click",()=>{cookingPanel.hidden=true;});
document.getElementById("cook-meat").addEventListener("click",()=>{if(state.inventory.meat<1||state.inventory.branches<1){cookStatus.textContent="Falta 1 carne e 1 galho para assar a carne.";return;}state.inventory.meat--;state.inventory.branches--;state.inventory.meals++;saveState();cookStatus.textContent="Carne assada preparada! Ela pode ser consumida ou guardada.";notify("Carne assada preparada.");renderCooking();renderCrafting();});
document.getElementById("cook-meal").addEventListener("click",()=>{if(state.inventory.berries<2||state.inventory.branches<1){cookStatus.textContent="Faltam 2 bagas e 1 galho para preparar a refeição.";return;}state.inventory.berries-=2;state.inventory.branches--;state.inventory.meals++;saveState();cookStatus.textContent="Refeição preparada! Você pode comê-la agora ou guardar para depois.";notify("Refeição cozida preparada.");renderCooking();renderCrafting();});
document.getElementById("eat-meal").addEventListener("click",()=>{if(state.inventory.meals<1||state.hunger>=100)return;state.inventory.meals--;state.hunger=Math.min(100,state.hunger+45);saveState();cookStatus.textContent="Você comeu uma refeição cozida. +45% de saciedade.";notify("Refeição consumida: +45 de saciedade.");updateClock(0);renderCooking();renderCrafting();});
function renderStorage(){if(!activeStorageChest)return;storageInventory.textContent=Object.entries(storageLabels).map(([key,label])=>label+": "+(activeStorageChest.inventory[key]||0)+" no baú · "+(state.inventory[key]||0)+" na mochila").join("\n");}
function openStorage(chest){activeStorageChest=chest;storagePanel.hidden=false;renderStorage();gatherPrompt.hidden=true;talkPrompt.hidden=true;storageStatus.textContent="Escolha o material e a quantidade para guardar ou retirar.";}
function closeStorage(){storagePanel.hidden=true;activeStorageChest=null;}
document.getElementById("storage-close").addEventListener("click",closeStorage);
document.getElementById("storage-deposit").addEventListener("click",()=>{if(!activeStorageChest)return;const key=storageSelect.value,amount=Math.max(1,Math.floor(Number(storageAmount.value)||1)),available=state.inventory[key]||0;if(available<1){storageStatus.textContent="Você não tem esse material na mochila.";return;}const moved=Math.min(amount,available);state.inventory[key]-=moved;activeStorageChest.inventory[key]=(activeStorageChest.inventory[key]||0)+moved;saveState();storageStatus.textContent="Guardado: "+moved+" · "+storageLabels[key]+".";renderStorage();renderCrafting();});
document.getElementById("storage-withdraw").addEventListener("click",()=>{if(!activeStorageChest)return;const key=storageSelect.value,amount=Math.max(1,Math.floor(Number(storageAmount.value)||1)),available=activeStorageChest.inventory[key]||0;if(available<1){storageStatus.textContent="O baú não tem esse material.";return;}const moved=Math.min(amount,available);activeStorageChest.inventory[key]-=moved;state.inventory[key]=(state.inventory[key]||0)+moved;saveState();storageStatus.textContent="Retirado: "+moved+" · "+storageLabels[key]+".";renderStorage();renderCrafting();});
function nearLoom(){return placedLooms.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<7);}
function nearBruna(){const npc=villagers.find(v=>v.id==="bruna");return !!npc&&Math.hypot(player.x-npc.group.position.x,player.z-npc.group.position.z)<7;}function nearTailoringShop(){return placedTailoringShops.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<8);}function canUseTailor(){return tailorAtWorkshop?nearTailoringShop():nearBruna();}
const tailorRecipes={tunic:{label:"Túnica simples",cost:{fabric:2,hide:1}},trousers:{label:"Calças de tecido",cost:{fabric:1,thread:1}},cloak:{label:"Capa de lã",cost:{fabric:2,thread:2,hide:1}},vest:{label:"Colete de viajante",cost:{fabric:2,thread:1,hide:1}},dress:{label:"Vestido campestre",cost:{fabric:3,thread:2}}};
function canTailor(key){return Object.entries(tailorRecipes[key].cost).every(([k,v])=>(state.inventory[k]||0)>=v);}
function updateClothingAppearance(){const palette={natural:0x8a633e,forest:0x536b45,blue:0x496b89,wine:0x783f4b,ochre:0xb18a43};const base=state.equippedClothes.cloak?0x66516f:state.equippedClothes.dress?0x8a633e:state.equippedClothes.vest?0x76513b:state.equippedClothes.tunic?0x8a633e:0x493b30;clothingSleeveMat.color.setHex(state.clothingColor==="natural"?base:(palette[state.clothingColor]||base));}
function renderTailor(){tailorInfo.textContent="Tecidos: "+state.inventory.fabric+" · Fios: "+state.inventory.thread+" · Couro: "+state.inventory.hide+"\\nVestindo: "+Object.keys(tailorRecipes).filter(k=>state.equippedClothes[k]).map(k=>tailorRecipes[k].label).join(", ");tailorPanel.querySelectorAll("[data-tailor-action]").forEach(btn=>{const key=btn.dataset.tailorAction,owned=state.inventory[key]||0,equipped=!!state.equippedClothes[key];btn.textContent=equipped?"EM USO":owned?"VESTIR "+tailorRecipes[key].label.toUpperCase():"COSTURAR "+tailorRecipes[key].label.toUpperCase();btn.disabled=!canUseTailor()||equipped||(!owned&&!canTailor(key));});const colorSelect=document.getElementById("clothing-color");if(colorSelect)colorSelect.value=state.clothingColor||"natural";const dyeButton=document.getElementById("clothing-dye");if(dyeButton)dyeButton.disabled=!canUseTailor()||state.inventory.berries<2||!Object.values(state.equippedClothes).some(Boolean);updateClothingAppearance();}
function openTailor(){tailorAtWorkshop=false;tailorPanel.querySelector("h2").textContent="Ateliê de Bruna";tailorPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderTailor();tailorStatus.textContent="Bruna pode costurar roupas com tecidos, fios e couro. As peças são produzidas com os materiais que você trouxe.";}function openTailoringWorkshop(){tailorAtWorkshop=true;tailorPanel.querySelector("h2").textContent="Oficina de costura";tailorPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderTailor();tailorStatus.textContent="Você está trabalhando na oficina da sua vila. Produza ou vista roupas usando seus próprios materiais.";}
function closeTailor(){tailorPanel.hidden=true;tailorAtWorkshop=false;}
document.getElementById("tailor-close").addEventListener("click",closeTailor);
document.getElementById("clothing-dye").addEventListener("click",()=>{if(!canUseTailor()){tailorStatus.textContent="Aproxime-se de uma oficina de costura para tingir suas roupas.";return;}if(!Object.values(state.equippedClothes).some(Boolean)){tailorStatus.textContent="Vista uma peça antes de tingi-la.";return;}if(state.inventory.berries<2){tailorStatus.textContent="Você precisa de 2 bagas silvestres para preparar a tintura.";return;}state.inventory.berries-=2;state.clothingColor=document.getElementById("clothing-color").value;saveState();renderTailor();renderCrafting();tailorStatus.textContent="Tintura aplicada às roupas equipadas!";notify("Suas roupas ganharam uma nova cor.");});
document.getElementById("tailor-unequip").addEventListener("click",()=>{if(!canUseTailor()){tailorStatus.textContent="Aproxime-se de Bruna para trocar suas roupas.";return;}state.equippedClothes={tunic:false,trousers:false,cloak:false,vest:false,dress:false};saveState();renderTailor();tailorStatus.textContent="Você guardou as peças que estava vestindo.";});
tailorPanel.querySelectorAll("[data-tailor-action]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.tailorAction;if(!canUseTailor()){tailorStatus.textContent="Aproxime-se de Bruna para costurar ou trocar de roupa.";return;}if(state.inventory[key]>0){state.equippedClothes[key]=true;tailorStatus.textContent=tailorRecipes[key].label+" vestida.";notify(tailorRecipes[key].label+" equipada.");}else{const recipe=tailorRecipes[key];if(!canTailor(key)){tailorStatus.textContent="Materiais insuficientes. Reúna os tecidos, fios e couro indicados.";return;}for(const [material,amount] of Object.entries(recipe.cost))state.inventory[material]-=amount;state.inventory[key]++;state.equippedClothes[key]=true;tailorStatus.textContent=recipe.label+" costurada e vestida.";notify("Você costurou: "+recipe.label+".");}saveState();renderTailor();renderCrafting();}));
function renderLoom(){loomInfo.textContent="Lã: "+state.inventory.wool+" · Fios: "+state.inventory.thread+" · Tecidos: "+state.inventory.fabric;loomPanel.querySelector('[data-loom-craft="thread"]').disabled=state.inventory.wool<1;loomPanel.querySelector('[data-loom-craft="fabric"]').disabled=state.inventory.thread<3;}
function openLoom(){loomPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderLoom();loomStatus.textContent="Transforme a lã em fios e depois reúna fios suficientes para tecer um tecido.";}
function closeLoom(){loomPanel.hidden=true;}
document.getElementById("loom-close").addEventListener("click",closeLoom);
loomPanel.querySelectorAll("[data-loom-craft]").forEach(btn=>btn.addEventListener("click",()=>{if(!nearLoom()){loomStatus.textContent="Aproxime-se do tear para produzir.";return;}const key=btn.dataset.loomCraft;if(key==="thread"){if(state.inventory.wool<1){loomStatus.textContent="Você precisa de pelo menos 1 lã.";return;}state.inventory.wool--;state.inventory.thread+=2;loomStatus.textContent="Fiação concluída: +2 fios.";notify("A lã foi transformada em 2 fios.");}else{if(state.inventory.thread<3){loomStatus.textContent="Reúna 3 fios para tecer 1 tecido.";return;}state.inventory.thread-=3;state.inventory.fabric++;loomStatus.textContent="Tecelagem concluída: +1 tecido.";notify("Um tecido foi produzido.");}saveState();renderLoom();renderCrafting();}));
function nearCarpentry(){return placedCarpentryShops.some(b=>Math.hypot(player.x-b.position.x,player.z-b.position.z)<8);}
const carpentryRecipes={planks:{label:"Tábuas de madeira",cost:3,gain:2},beams:{label:"Vigas de madeira",cost:4,gain:1}};
function canCraftCarpentry(key){return nearCarpentry()&&state.inventory.wood>=carpentryRecipes[key].cost;}
