function closeCarpentry(){carpentryPanel.hidden=true;}
document.getElementById("carpentry-close").addEventListener("click",closeCarpentry);
carpentryPanel.querySelectorAll("[data-carpentry-craft]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.carpentryCraft,r=carpentryRecipes[key];if(!canCraftCarpentry(key)){carpentryStatus.textContent="Aproxime-se da oficina e reúna madeira suficiente.";return;}state.inventory.wood-=r.cost;state.inventory[key]+=r.gain;saveState();carpentryStatus.textContent=r.label+" produzidas: +"+r.gain+". Materiais atualizados.";notify(r.label+" produzidas.");renderCarpentry();}));
function renderCrafting(){const shelterButton=craftPanel.querySelector("[data-build-shelter]");if(shelterButton)shelterButton.disabled=!canBuildShelter();const workbenchButton=craftPanel.querySelector("[data-build-workbench]");if(workbenchButton)workbenchButton.disabled=!canBuildWorkbench();const carpentryButton=craftPanel.querySelector("[data-build-carpentry]");if(carpentryButton)carpentryButton.disabled=!canBuildCarpentry();const chestBuildButton=craftPanel.querySelector("[data-build-chest]");if(chestBuildButton)chestBuildButton.disabled=!canBuildChest();const chickenCoopButton=craftPanel.querySelector("[data-build-chicken-coop]");if(chickenCoopButton)chickenCoopButton.disabled=!canBuildChickenCoop();const sheepPenButton=craftPanel.querySelector("[data-build-sheep-pen]");if(sheepPenButton)sheepPenButton.disabled=false;const loomButton=craftPanel.querySelector("[data-build-loom]");if(loomButton)loomButton.disabled=!canBuildLoom();const tailoringButton=craftPanel.querySelector("[data-build-tailoring]");if(tailoringButton)tailoringButton.disabled=!canBuildTailoring();const fieldButton=craftPanel.querySelector("[data-build-field]");if(fieldButton)fieldButton.disabled=!state.tools.hoe;inventoryText.textContent="Bagas: "+state.inventory.berries+"   Galhos: "+state.inventory.branches+"   Pedras: "+state.inventory.stones+"   Fibras: "+state.inventory.fiber+"   Madeira: "+state.inventory.wood+"   Carne: "+state.inventory.meat+"   Couro: "+state.inventory.hide+"   Sementes: "+state.inventory.wheatSeeds+"   Trigo: "+state.inventory.wheat+"   Ovos: "+state.inventory.eggs+"   Lã: "+state.inventory.wool+"   Fios: "+state.inventory.thread+"   Tecidos: "+state.inventory.fabric+"   Túnicas: "+state.inventory.tunic+"   Calças: "+state.inventory.trousers+"   Capas: "+state.inventory.cloak+"\\nEnxada: "+(state.tools.hoe?"fabricada":"não fabricada")+"   Lança: "+(state.tools.spear?"fabricada":"não fabricada")+"   Machado: "+(state.tools.axeAdvanced?"reforçado":state.tools.axe?"rudimentar":"não fabricado")+"   Picareta: "+(state.tools.pickaxeAdvanced?"reforçada":state.tools.pickaxe?"rudimentar":"não fabricada")+"\\nTochas: "+state.items.torches+"   Fogueiras: "+state.items.campfires;craftPanel.querySelectorAll("[data-craft]").forEach(btn=>{const key=btn.dataset.craft;btn.disabled=!canCraft(key);});campfirePlace.hidden=state.items.campfires<1;const eatBerries=document.getElementById("eat-berries");if(eatBerries)eatBerries.disabled=state.inventory.berries<1||state.hunger>=100;const hungerCraft=document.getElementById("hunger-craft-status");if(hungerCraft)hungerCraft.textContent="Fome: "+Math.round(state.hunger)+"% · Bagas: "+state.inventory.berries+" · Refeições: "+state.inventory.meals;}
function openCrafting(){craftVisible=true;craftPanel.hidden=false;gatherPrompt.hidden=true;renderCrafting();}
function closeCrafting(){craftVisible=false;craftPanel.hidden=true;}
const benchPanel=document.getElementById("bench-panel"),benchInventory=document.getElementById("bench-inventory"),benchStatus=document.getElementById("bench-status");
function renderBench(){benchInventory.textContent="Madeira: "+state.inventory.wood+" · Pedras: "+state.inventory.stones+" · Galhos: "+state.inventory.branches+" · Fibras: "+state.inventory.fiber+"\\nMachado: "+(state.tools.axeAdvanced?"reforçado":state.tools.axe?"rudimentar":"não fabricado")+" · Picareta: "+(state.tools.pickaxeAdvanced?"reforçada":state.tools.pickaxe?"rudimentar":"não fabricada");benchPanel.querySelectorAll("[data-bench-craft]").forEach(btn=>{btn.disabled=!canCraftAdvanced(btn.dataset.benchCraft);});}
function openBench(){if(benchVisible)return;benchVisible=true;benchPanel.hidden=false;gatherPrompt.hidden=true;talkPrompt.hidden=true;renderBench();}
function closeBench(){benchVisible=false;benchPanel.hidden=true;}
document.getElementById("bench-close").addEventListener("click",closeBench);
benchPanel.querySelectorAll("[data-bench-craft]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.benchCraft,r=advancedRecipes[key];if(!canCraftAdvanced(key)){benchStatus.textContent="Você precisa estar perto da bancada, ter a ferramenta rudimentar e reunir todos os materiais.";return;}for(const [k,v] of Object.entries(r.cost))state.inventory[k]-=v;state.tools[key+"Advanced"]=true;saveState();benchStatus.textContent=r.label+" fabricado com sucesso.";notify("Você fabricou: "+r.label+".");renderBench();}));
craftOpen.addEventListener("click",openCrafting);craftClose.addEventListener("click",closeCrafting);
document.getElementById("eat-berries").addEventListener("click",()=>{if(state.inventory.berries<1){craftStatus.textContent="Você precisa coletar bagas silvestres primeiro.";return;}if(state.hunger>=100){craftStatus.textContent="Você não está com fome agora.";return;}state.inventory.berries--;state.hunger=Math.min(100,state.hunger+25);saveState();craftStatus.textContent="Você comeu bagas silvestres. A fome foi reduzida.";notify("Você se alimentou: +25 de saciedade.");updateClock(0);renderCrafting();});
craftPanel.querySelectorAll("[data-craft]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.craft,r=recipes[key];if(!canCraft(key)){craftStatus.textContent="Ainda faltam materiais para esta receita.";return;}for(const [k,v] of Object.entries(r.cost))state.inventory[k]-=v;if(key==="axe")state.tools.axe=true;else if(key==="pickaxe")state.tools.pickaxe=true;else if(key==="spear")state.tools.spear=true;else if(key==="hoe")state.tools.hoe=true;else if(key==="torch")state.items.torches++;else state.items.campfires++;saveState();craftStatus.textContent=r.label+" fabricado com sucesso.";notify(r.label+" fabricado.");renderCrafting();}));

campfirePlace.addEventListener("click",()=>startPlacement("campfire"));const shelterBuildButton=craftPanel.querySelector("[data-build-shelter]");shelterBuildButton?.addEventListener("click",()=>startPlacement("shelter"));const workbenchBuildButton=craftPanel.querySelector("[data-build-workbench]");workbenchBuildButton?.addEventListener("click",()=>startPlacement("workbench"));const carpentryBuildButton=craftPanel.querySelector("[data-build-carpentry]");carpentryBuildButton?.addEventListener("click",()=>startPlacement("carpentry"));const chestBuildButton=craftPanel.querySelector("[data-build-chest]");chestBuildButton?.addEventListener("click",()=>startPlacement("chest"));const fieldBuildButton=craftPanel.querySelector("[data-build-field]");fieldBuildButton?.addEventListener("click",()=>startPlacement("field"));const chickenCoopBuildButton=craftPanel.querySelector("[data-build-chicken-coop]");chickenCoopBuildButton?.addEventListener("click",()=>startPlacement("chickenCoop"));const sheepPenBuildButton=craftPanel.querySelector("[data-build-sheep-pen]");sheepPenBuildButton?.addEventListener("click",()=>startPlacement("sheepPen"));const loomBuildButton=craftPanel.querySelector("[data-build-loom]");loomBuildButton?.addEventListener("click",()=>startPlacement("loom"));const tailoringBuildButton=craftPanel.querySelector("[data-build-tailoring]");tailoringBuildButton?.addEventListener("click",()=>startPlacement("tailoring"));placementConfirm.addEventListener("click",confirmPlacement);placementCancel.addEventListener("click",cancelPlacement);
document.getElementById("placement-rotate-left").addEventListener("click",()=>rotateShelter(-Math.PI/4));document.getElementById("placement-rotate-right").addEventListener("click",()=>rotateShelter(Math.PI/4));
function rotateShelter(delta){if(!placementMode||!(selectedPlacementKind==="shelter"||selectedPlacementKind==="workbench"||selectedPlacementKind==="carpentry"||selectedPlacementKind==="chest"||selectedPlacementKind==="field"||selectedPlacementKind==="chickenCoop"||selectedPlacementKind==="sheepPen"||selectedPlacementKind==="loom"||selectedPlacementKind==="tailoring")||!activeShelterPreview)return;placementRotation=(placementRotation+delta+Math.PI*2)%(Math.PI*2);activeShelterPreview.rotation.y=placementRotation;}
function performGather(target){if(!target)return;if(target.kind==="chickenCoop"){openChickenCoop(target.index);return;}if(target.kind==="sheepPen"){openSheepPen(target.index);return;}if(target.kind==="field"){const entry=target.field;if(entry.data.plantedDay===null||entry.data.plantedDay===undefined){if(!state.tools.hoe){notify("Fabrique uma enxada para trabalhar a terra.");return;}if(state.inventory.wheatSeeds<1){notify("Você precisa encontrar sementes silvestres antes de plantar.");return;}state.inventory.wheatSeeds--;entry.data.plantedDay=state.day;entry.stage=-1;refreshFieldVisual(entry);saveState();notify("Trigo plantado. A colheita ficará pronta em 3 dias.");}else if(state.day-entry.data.plantedDay>=2){state.inventory.wheat+=5;state.inventory.wheatSeeds++;entry.data.plantedDay=null;entry.stage=-1;refreshFieldVisual(entry);saveState();notify("Colheita realizada: +5 trigo e +1 semente.");}else{const remaining=3-(state.day-entry.data.plantedDay);notify("O trigo ainda está crescendo. Faltam "+remaining+" dia(s) para a colheita.");}renderCrafting();return;}if(target.kind==="animal"){if(!state.tools.spear){notify("Você precisa fabricar uma lança rudimentar para caçar.");return;}const animal=target.animal;state.huntedAnimals=state.huntedAnimals.filter(v=>v.id!==animal.id);state.huntedAnimals.push({id:animal.id,day:state.day});animal.group.visible=false;animal.alive=false;state.inventory.meat+=2;state.inventory.hide+=1;notify("Caça realizada: +2 carnes e +1 couro.");saveState();renderCrafting();currentGatherable=null;gatherPrompt.hidden=true;return;}if(target.kind==="tree"){const index=target.index;setTreeVisible(index,false);state.felledTrees.push({index,day:state.day});const woodGain=state.tools.axeAdvanced?4:2,branchGain=state.tools.axeAdvanced?3:2;state.inventory.wood+=woodGain;state.inventory.branches+=branchGain;notify("Árvore cortada: +"+woodGain+" madeiras e +"+branchGain+" galhos.");}else{const node=target.node;if(node.type==="ore"&&!state.tools.pickaxe){notify("Você precisa de uma picareta para extrair este veio de pedra.");return;}if(node.type==="branch")state.inventory.branches+=node.amount;else if(node.type==="stone")state.inventory.stones+=node.amount;else if(node.type==="fiber")state.inventory.fiber+=node.amount;else if(node.type==="berry")state.inventory.berries+=node.amount;else if(node.type==="seed")state.inventory.wheatSeeds+=node.amount;else state.inventory.stones+=node.amount*(node.type==="ore"&&state.tools.pickaxeAdvanced?2:1);state.harvestedNodes[node.id]=state.day;node.group.visible=false;notify(node.type==="berry"?"Bagas silvestres coletadas: +"+node.amount+".":node.type==="seed"?"Sementes de trigo silvestre coletadas: +"+node.amount+".":node.type==="ore"?"Minério extraído: +"+node.amount+" pedras.":"Recursos coletados.");}saveState();renderCrafting();currentGatherable=null;gatherPrompt.hidden=true;}
gatherButton.addEventListener("click",()=>performGather(currentGatherable));
 let pendingPlot=null;
 function validPlot(x,z){if(Math.abs(x)>82||Math.abs(z)>82)return"Escolha uma área mais distante dos limites do vale.";if(riverDistance(x,z)<17)return"Esse terreno fica muito perto do rio. Procure uma área mais segura.";if(Math.hypot(x-48,z+82)<28)return"Escolha um terreno afastado da Vila Vizinha.";const base=groundHeight(x,z);for(const [dx,dz] of [[-10,0],[10,0],[0,-10],[0,10],[-7,-7],[7,-7],[-7,7],[7,7]])if(Math.abs(groundHeight(x+dx,z+dz)-base)>1.65)return"Esse terreno é muito inclinado. Procure uma área mais plana.";return"";}
