 function updateClock(add){state.minute+=add;while(state.minute>=DAY_MINUTES){state.minute-=DAY_MINUTES;state.day++;}if(state.started&&add>0){state.hungerProgress+=add;while(state.hungerProgress>=120){state.hungerProgress-=120;const before=state.hunger;state.hunger=Math.max(0,state.hunger-1);if(before>0&&state.hunger===30)notify("A fome está aumentando. Procure alimento.");if(before>0&&state.hunger===10)notify("Você está com muita fome. Coma algo.");if(before>0&&state.hunger===0)notify("Você está exausto pela fome. Encontre alimento.");}}const h=Math.floor(state.minute/60),m=Math.floor(state.minute%60);clockLabel.textContent="DIA "+state.day+" · "+String(h).padStart(2,"0")+":"+String(m).padStart(2,"0");const hungerFill=document.getElementById("hunger-fill"),hungerValue=document.getElementById("hunger-value");if(hungerFill)hungerFill.style.width=state.hunger+"%";if(hungerValue)hungerValue.textContent=Math.round(state.hunger)+"%";}updateClock(0);
